"""Architecture ladder 2 (docs/prior_v2_plan.md 5.2) - the one-page results record, generated from the source JSONs only:
results_judge_v3.json (E9 sign tests + baselines), train_summary.json (curves), target_content.json (target -> value R2),
peak_smoke.json (memory). Writes summary.md (view) and ladder_summary.json (per-model record for later analysis) next to
this file. Run: uv run python eval/arch_ladder_2026-09-11/build_summary.py"""
import json
from pathlib import Path

R = Path(__file__).resolve().parents[2]; D = Path(__file__).parent
JJ = json.load(open(R / "eval/prior_ladder_2026-09-10/results_judge_v3.json")); J, B = JJ["results"], JJ["baselines"]
S = json.load(open(D / "train_summary.json")); TC = json.load(open(D / "target_content.json"))["runs"]
PK = {(p["arm"], p["ckpt_pass2"]): p for p in json.load(open(D / "peak_smoke.json"))["rows"]}
PFN, SNAP, V3, DUAL = "PFN_tabicl2_ds_s0", "TabularJEPA_v3_tabicl2_s0_snap9250", "TabularJEPA_v3_tabicl2_s0", "v4_dual_split_ctx_tw4_diff_lam1_lr5e-4_mixed_cell_s0"
HE, DA, SG = "TabularJEPA_v3_tabicl2_headenc_s0", "TabularJEPA_v3_tabicl2_dae_headenc_s0", "TabularJEPA_v3_tabicl2_sigreg_headenc_s0"
MODELS = [  # (run, role, structure)
    (PFN, "baseline", "encoder + bar head, value loss only (no latent term)"),
    (V3, "reference (collapsed)", "encoder -> predictor(4) -> bar head ON the predictor; EMA diff latent target"),
    (SNAP, "reference (v3 best snapshot, 9250)", "same as v3"),
    (HE, "run 1", "v3 with the bar head moved onto the ENCODER output; predictor latent-only; EMA diff target"),
    (DA, "run 2", "headenc + EMA copy replaced by a denoising y-encoder (sigma .5, own bar-CE reconstruction), embedding = target"),
    (SG, "run 3", "headenc + EMA copy replaced by LeWM SIGReg (same encoder full pass -> projector, no detach, additive lambda .05)"),
    (DUAL, "reference (real-prior dual_split 20k)", "previous best JEPA run, real-data-matched prior"),
]
def pair(rule, a, b, task, lab):
    r = J.get(f"{rule}|{a}|{b}|{task}|{lab}"); return None if r is None else f"{r['win']}:{r['loss']}"
def vs_pfn(run):
    for rule in ("L2", "R2", "prior|ds"):
        if pair(rule, run, PFN, "clf", "all"): return rule, run, PFN
        if pair(rule, PFN, run, "clf", "all"): return rule, PFN, run
    return None
def vals(run):
    p = R / "runs" / run / "metrics.jsonl"
    if not p.exists(): return None
    va = [json.loads(l) for l in p.read_text().splitlines() if l.strip() and "val_mse" in l]
    va = [v for v in va if "val_mse" in v]; lo = min(va, key=lambda v: v["val_mse"])
    return dict(last=va[-1]["val_mse"], min=lo["val_mse"], min_step=lo["step"], last_step=va[-1]["step"])
rec, md = {}, ["<!-- generated by eval/arch_ladder_2026-09-11/build_summary.py from the source JSONs; do not edit -->",
              "# Architecture ladder 2 - results record (2026-09-11)", "",
              "Common recipe: TabICLv2 prior, 20k steps, batch 4, lr 5e-4, emb 256 / 6 layers, rows 128-1024, cell budget 65536; E9 = 147 real datasets, K_FEAT 64 / CTX 1024, exact two-sided sign test per dataset.", "",
              "| model | role | structure |", "|---|---|---|"]
for run, role, struct in MODELS:
    md.append(f"| `{run}` | {role} | {struct} |")
md += ["", "## E9 (real data)", "", "| model | clf mean acc | vs PFN ds clf / 6-10 cls / reg | vs v3 snap9250 clf | vs HistGB / logreg (clf) | reg mean r2 | vs HistGB / ridge (reg) |", "|---|---|---|---|---|---|---|"]
for run, role, struct in MODELS:
    b = B.get(run)
    if not b: continue
    p = vs_pfn(run); pv = "baseline" if run == PFN else (f"{pair(*p, 'clf', 'all')} / {pair(*p, 'clf', 'ncls=6-10')} / {pair(*p, 'reg', 'all')}" + (" (PFN first)" if p and p[1] == PFN else "") if p else "-")
    def flipped(rule, a, b):                       # judge rows are stored (a, b); report with `run` first
        r = J.get(f"{rule}|{a}|{b}|clf|all"); return None if r is None else f"{r['loss']}:{r['win']}"
    sn = "baseline" if run == SNAP else (pair("L2", run, SNAP, "clf", "all") or flipped("R1", SNAP, run) or flipped("R2", SNAP, run) or flipped("R3", SNAP, run) or "-")
    rec[run] = dict(role=role, structure=struct, e9=dict(clf_mean=b["clf"]["mean"], clf_n=b["clf"]["n"], reg_mean=b["reg"]["mean"], reg_n=b["reg"]["n"],
                    vs_pfn_ds=pv, vs_snap9250_clf=sn, vs_histgb_clf=b["clf"]["vs_histgb"], vs_logreg_clf=b["clf"]["vs_logreg"], vs_histgb_reg=b["reg"]["vs_histgb"], vs_ridge_reg=b["reg"]["vs_ridge"]))
    md.append(f"| `{run}` | {b['clf']['mean']:.3f} | {pv} | {sn} | {b['clf']['vs_histgb'][0]}:{b['clf']['vs_histgb'][1]} / {b['clf']['vs_logreg'][0]}:{b['clf']['vs_logreg'][1]} | {b['reg']['mean']:.3f} | {b['reg']['vs_histgb'][0]}:{b['reg']['vs_histgb'][1]} / {b['reg']['vs_ridge'][0]}:{b['reg']['vs_ridge'][1]} |")
md += [f"", f"Baseline means: HistGB clf {B[PFN]['clf']['histgb_mean']:.3f} / logreg {B[PFN]['clf']['logreg_mean']:.3f}; HistGB reg {B[PFN]['reg']['histgb_mean']:.3f} / ridge {B[PFN]['reg']['ridge_mean']:.3f}.",
       f"Between the arms (L2x, clf all / reg): headenc vs dae {pair('L2x', HE, DA, 'clf', 'all')} / {pair('L2x', HE, DA, 'reg', 'all')}, headenc vs sigreg {pair('L2x', HE, SG, 'clf', 'all')} / {pair('L2x', HE, SG, 'reg', 'all')}, dae vs sigreg {pair('L2x', DA, SG, 'clf', 'all')} / {pair('L2x', DA, SG, 'reg', 'all')}.",
       "", "## Training curves (20k)", "", "| model | val_mse 20k | min val_mse @ step | survived (never back to the .936 constant map) | latent: val_jepa / target cos / pred_std / target erank | hours | peak GPU MiB |", "|---|---|---|---|---|---|---|"]
for run, role, struct in MODELS:
    v = vals(run)
    if v is None: continue
    s = S.get(run); arm = run.replace("TabularJEPA_v3_tabicl2_", "").replace("_s0", "")
    pk = PK.get((arm, True)) or PK.get((arm, False))
    lat = f"{s['last']['val_jepa']} / {s['last']['tgt_cos']} / {s['last']['pred_std']} / {s['last']['tgt_erank']}" if s else "-"
    rec.setdefault(run, {})["train"] = dict(val_mse_20k=v["last"], min_val_mse=v["min"], min_step=v["min_step"], survived=s["survived"] if s else None, hours=round(s["sec_total"] / 3600, 2) if s else None, peak_mib=pk["peak_mib"] if pk else None, latent=s["last"] if s else None)
    md.append(f"| `{run}` | {v['last']} | {v['min']} @ {v['min_step']} | {s['survived'] if s else '-'} | {lat} | {s['sec_total']/3600:.2f} | {pk['peak_mib'] if pk else '-'}{' (ckpt_pass2)' if pk and pk['ckpt_pass2'] else ''} |" if s else f"| `{run}` | {v['last']} | {v['min']} @ {v['min_step']} | - | - | - | - |")
DS8K = "PFN_tabicl2_ds_s0_snap8000"   # step-matched read (2026-09-13): ds at the snapshot whose val_mse first matches headenc 20k
if f"L2t|{HE}|{DS8K}|clf|all" in J:
    DC = json.load(open(D / "device_check.json")) if (D / "device_check.json").exists() else None
    md += ["", "## Step-matched read (L2t, 2026-09-13): the ds baseline at the snapshot whose val_mse first matches headenc's 20k value (ds 7750 -> nearest snapshot 8000)", "",
           "| A | B | clf all | ncls=2 | ncls=3-5 | ncls=6-10 | reg | clf mean A vs B | reg mean A vs B |", "|---|---|---|---|---|---|---|---|---|"]
    for a in (HE, DA, PFN):
        c = {lab: J[f"L2t|{a}|{DS8K}|clf|{lab}"] for lab in ("all", "ncls=2", "ncls=3-5", "ncls=6-10")}; g = J[f"L2t|{a}|{DS8K}|reg|all"]
        rec.setdefault(a, {})["vs_ds_snap8000"] = dict(clf={k: [v["win"], v["loss"], v["p"]] for k, v in c.items()}, reg=[g["win"], g["loss"], g["p"]],
                                                       clf_means=[c["all"]["mean_a"], c["all"]["mean_b"]], reg_means=[g["mean_a"], g["mean_b"]])
        md.append(f"| `{a}` | `{DS8K}` | " + " | ".join(f"{c[k]['win']}:{c[k]['loss']}" for k in c) + f" | {g['win']}:{g['loss']} | {c['all']['mean_a']:.3f} vs {c['all']['mean_b']:.3f} | {g['mean_a']:.3f} vs {g['mean_b']:.3f} |")
    if DC:
        md.append(f"\nDevice check (device_check.json): the snapshot-8000 checkpoint scored by the same suite on the local CPU and on the server GPU agrees on {DC['n']}/{DC['n']} datasets (max |delta| {DC['max_abs_delta']}, sklearn baseline cells mismatching {DC['baseline_cells_mismatch']}); E9 passes can run on either device.")
L3 = sorted({k.split("|")[1] + "|" + k.split("|")[2] for k in J if k.startswith("L3|") and k.endswith("|clf|all")},
            key=lambda ab: (ab.split("|")[0].split("_snap")[0], int(ab.split("|")[0].split("_snap")[1]) if "_snap" in ab.split("|")[0] else 10**9, ab.split("|")[1]))   # (arm, step, B): total order = deterministic file
if L3:   # open-horizon pair (plan 5.3, 2026-09-14): every scored *_conv_s0 snapshot; grows as e9_gpu.sh passes are fetched (e9_fetch.sh)
    md += ["", "## Open-horizon pair (L3, plan 5.3, from 2026-09-14): scored snapshots of the *_conv_s0 runs vs the 20k ds baseline, and headenc snapshots vs the ds snapshot at the same step", "",
           "| A | B | clf all | ncls=2 | ncls=3-5 | ncls=6-10 | reg | clf mean A vs B | reg mean A vs B |", "|---|---|---|---|---|---|---|---|---|"]
    for ab in L3:
        a, b = ab.split("|")
        c = {lab: J[f"L3|{a}|{b}|clf|{lab}"] for lab in ("all", "ncls=2", "ncls=3-5", "ncls=6-10")}; g = J[f"L3|{a}|{b}|reg|all"]
        rec.setdefault(a, {}).setdefault("L3", {})[b] = dict(clf={k: [v["win"], v["loss"], v["p"]] for k, v in c.items()}, reg=[g["win"], g["loss"], g["p"]],
                                                            clf_means=[c["all"]["mean_a"], c["all"]["mean_b"]], reg_means=[g["mean_a"], g["mean_b"]])
        md.append(f"| `{a}` | `{b}` | " + " | ".join(f"{c[k]['win']}:{c[k]['loss']}" for k in c) + f" | {g['win']}:{g['loss']} | {c['all']['mean_a']:.3f} vs {c['all']['mean_b']:.3f} | {g['mean_a']:.3f} vs {g['mean_b']:.3f} |")
md += ["", "## Target -> value decodability (target_content.py: ctx 128, 8 x 8 tables of the run's prior, ridge on half / R2 on the other half)", "",
       "| model | R2 value <- latent target | R2 value <- noise-free encoding (dae) | R2 value <- prediction | target erank | pred erank |", "|---|---|---|---|---|---|"]
for run in (HE, DA, SG):
    t = TC[run]; rec[run]["probe"] = t
    md.append(f"| `{run}` | {t['target']['z_from_target']} | {t.get('target_noise_free', {}).get('z_from_target', '-')} | {t['pred']['z_from_pred']} | {t['target']['erank']} | {t['pred']['erank']} |")
md += ["", "Sources: `eval/prior_ladder_2026-09-10/results_judge_v3.json` (E9), `train_summary.json`, `target_content.json`, `peak_smoke.json`; verdict prose = `docs/prior_v2_plan.md` 5.2, history (18)."]
(D / "summary.md").write_text("\n".join(md) + "\n"); (D / "ladder_summary.json").write_text(json.dumps(rec, indent=1) + "\n")
print("wrote", D / "summary.md", D / "ladder_summary.json"); print("\n".join(md[6:14]))
